# ─────────────────────────────────────────────────────────────
# 공통 유틸 함수
# ─────────────────────────────────────────────────────────────
def create_lagged_features(X_raw, Y_vx, Y_vy, num_lags=NUM_LAGS):
    """타임랙 피처 생성 (과거 num_lags bins 평탄화)"""
    X_lag, vx_lag, vy_lag = [], [], []
    for t in range(num_lags, len(X_raw)):
        X_lag.append(X_raw[t - num_lags:t, :].flatten())
        vx_lag.append(Y_vx[t])
        vy_lag.append(Y_vy[t])
    return np.array(X_lag), np.array(vx_lag), np.array(vy_lag)


def apply_dynamic_weighting(X_feat, burst_power=BURST_POWER):
    """스파이크 버스트 구간 비선형 증폭"""
    return np.where(X_feat > 0, np.power(X_feat, burst_power), 0.0)


def run_cv_decoding(X_feat, Vx_tgt, Vy_tgt, n_splits=N_FOLDS, sigma=GAUSS_SIGMA):
    """
    5-fold CV → (r_x_list, r_y_list, last_fold_preds)
    last_fold_preds: (Vx_test, Vx_pred, Vy_test, Vy_pred) 마지막 fold
    """
    kf = KFold(n_splits=n_splits, shuffle=False)
    r_x_list, r_y_list = [], []
    last_preds = None

    for train_idx, test_idx in kf.split(X_feat):
        Xtr, Xte    = X_feat[train_idx], X_feat[test_idx]
        vxtr, vxte  = Vx_tgt[train_idx], Vx_tgt[test_idx]
        vytr, vyte  = Vy_tgt[train_idx], Vy_tgt[test_idx]

        mx = Ridge(alpha=RIDGE_ALPHA).fit(Xtr, vxtr)
        my = Ridge(alpha=RIDGE_ALPHA).fit(Xtr, vytr)

        vxp = gaussian_filter1d(mx.predict(Xte), sigma=sigma)
        vyp = gaussian_filter1d(my.predict(Xte), sigma=sigma)

        rx, _ = pearsonr(vxte, vxp)
        ry, _ = pearsonr(vyte, vyp)
        r_x_list.append(rx)
        r_y_list.append(ry)
        last_preds = (vxte, vxp, vyte, vyp)

    return r_x_list, r_y_list, last_preds


# ─────────────────────────────────────────────────────────────
# PHASE 2: 기저 성능 측정 (r_neural)
# ─────────────────────────────────────────────────────────────
print("\n" + "=" * 60)
