print("=" * 60)

X_lag, Vx_lag, Vy_lag       = create_lagged_features(X, Vx, Vy)
X_lag_dyn                   = apply_dynamic_weighting(X_lag)

r_x_folds, r_y_folds, last_base = run_cv_decoding(X_lag_dyn, Vx_lag, Vy_lag)

r_neural_x = float(np.mean(r_x_folds))
r_neural_y = float(np.mean(r_y_folds))
r_neural   = (r_neural_x + r_neural_y) / 2

print(f"r_neural_x (mean): {r_neural_x:.4f}")
print(f"r_neural_y (mean): {r_neural_y:.4f}")
print(f"r_neural   (avg):  {r_neural:.4f}  (논문 기준: {PAPER_R_NEURAL})")
print(f"논문 대비 차이:    {r_neural - PAPER_R_NEURAL:+.4f}")


