# ═══════════════════════════════════════════════════════════════
# PHASE 3: SER 강인성 비교 (4-Decoder)
# ═══════════════════════════════════════════════════════════════
print("\n" + "=" * 62)
print("PHASE 3: SER 강인성 비교 (4-Decoder)")
print("=" * 62)

ser_results = {name: {ser: [] for ser in SER_VALUES} for name in DECODER_NAMES}

for name in DECODER_NAMES:
    print(f"\n[{name}] SER 스윕...")
    for si, ser in enumerate(SER_VALUES):
        n_rep = 1 if ser == 0 else N_REPEATS
        for rep in range(n_rep):
            rng    = np.random.default_rng(seed=rep * 100 + si)
            X_corr = apply_SER(X_cpu, ser, rng=rng) if ser > 0 else X_cpu

            # 각 디코더에 맞는 SER 적용 데이터 준비
            current_X_feat = None
            current_X_peak_input = None # Initialize for each iteration

            if name == 'LSTM':
                X_seq_c  = create_sequential_features(X_corr)
                current_X_feat = apply_dynamic_weighting(X_seq_c).astype(np.float32)
            elif name == 'Kalman':
                X_obs_c  = get_kalman_obs(X_corr)
                current_X_feat = apply_dynamic_weighting(X_obs_c).astype(np.float32)
            else:  # Ridge, MLP
                # For Ridge and MLP, X_feat uses lagged features from X_corr
                X_lag_c, _, _ = create_lagged_features(X_corr, Vx_cpu, Vy_cpu)
                current_X_feat = apply_dynamic_weighting(X_lag_c).astype(np.float32)

                if name == 'MLP':
                    # For MLP, create peak features from X_corr
                    _, current_X_peak_input, _, _ = create_peak_aware_features(X_corr, Vx_cpu, Vy_cpu)


            # Call run_gpu_decoding with current_X_peak_input if it's MLP
            if name == 'MLP':
                rx_list, ry_list, _, _, _ = run_gpu_decoding(
                    name, current_X_feat, Vx_lag, Vy_lag, X_peak=current_X_peak_input
                )
            else:
                rx_list, ry_list, _, _, _ = run_gpu_decoding(
                    name, current_X_feat, Vx_lag, Vy_lag
                )

            r_ser = (np.mean(rx_list) + np.mean(ry_list)) / 2
            ser_results[name][ser].append(r_ser)
            print(f"  SER={ser:.0e}  rep={rep+1}/{n_rep}  r={r_ser:.4f}")

# 유지율 계산
retention = {}
for name in DECODER_NAMES:
    r_base = float(np.mean(ser_results[name][0]))
    retention[name] = {
        'mean': np.array([np.mean(ser_results[name][s]) / r_base for s in SER_VALUES]),
        'std':  np.array([np.std(ser_results[name][s])  / r_base for s in SER_VALUES]),
    }

print(f"\n{'─'*75}")
print(f"  {'SER':>8}", end='')
for name in DECODER_NAMES:
    print(f"  {name:>10}", end='')
print(f"  {'Paper':>8}")
paper_ref = {1e-4: 1.000, 1e-3: 0.888, 1e-2: 0.700}
for i, ser in enumerate(SER_VALUES):
    pv = paper_ref.get(ser, None)
    pv_str = f"{pv:.3f}" if pv else "   —"
    print(f"  {ser:.0e}  ", end='')
    for name in DECODER_NAMES:
        print(f"  {retention[name]['mean'][i]:>10.4f}", end='')
    print(f"  {pv_str:>8}")


